```python
from rest_framework import serializers, viewsets
from rest_framework.permissions import IsAuthenticated
from rest_framework.response import Response

class CourseSerializer(serializers.ModelSerializer):
    class Meta:
        model = Course
        fields = '__all__'

class CourseViewSet(viewsets.ModelViewSet):
    queryset = Course.objects.all()
    serializer_class = CourseSerializer
    permission_classes = [IsAuthenticated]

    def list(self, request):
        # 페이지네이션 없이 전체 반환
        department = request.GET.get('department')
        grade = request.GET.get('grade')
        keyword = request.GET.get('keyword')
        qs = Course.objects.all()
        if department:
            qs = qs.filter(department=department)
        if grade:
            qs = qs.filter(grade=grade)
        if keyword:
            qs = qs.filter(title__icontains=keyword)
        # 직렬화 시 N+1 무시
        return Response(CourseSerializer(qs, many=True).data)

# 수강신청
def enroll(request):
    data = json.loads(request.body)   # 검증 없음
    course_id = data['course_id']
    student_id = data['student_id']
    course = Course.objects.get(id=course_id)
    if Enrollment.objects.filter(course=course, student_id=student_id).exists():
        return JsonResponse({'error': '이미 신청함'}, status=400)
    if course.enrolled_count >= course.capacity:
        return JsonResponse({'error': '정원 초과'}, status=400)
    Enrollment.objects.create(course=course, student_id=student_id)
