아래 강의 수강신청 API 코드를 Django Ninja 컨벤션에 맞게 리팩토링해줘. Before/After/Reason 형식으로 보여줘.

```python
from rest_framework import serializers, viewsets
from rest_framework.decorators import action
from rest_framework.permissions import IsAuthenticated

class CourseSerializer(serializers.ModelSerializer):
    class Meta:
        model = Course
        fields = '__all__'

class CourseViewSet(viewsets.ModelViewSet):
    queryset = Course.objects.all()
    serializer_class = CourseSerializer
    permission_classes = [IsAuthenticated]
    authentication_classes = [TokenAuthentication]

    def list(self, request):
        qs = Course.objects.all()
        dept = request.GET.get('department')
        if dept:
            qs = qs.filter(department=dept)
        return Response(CourseSerializer(qs, many=True).data)

    @action(detail=True, methods=['post'])
    def enroll(self, request, pk):
        course = Course.objects.get(pk=pk)
        student_id = request.data.get('student_id')
        if not student_id:
            return Response({'error': 'student_id required'}, status=400)
        # 같은 요청 두 번 들어오면 두 번 등록됨
        Enrollment.objects.create(course=course, student_id=student_id)
        course.enrolled_count += 1
        course.save()
        return Response({'enrolled': True})
```
